async function WINDOW_ROOM(rm, window) {
  let p_ = 0, l = 0;
  if (rm == FRONT_YARD) {
    if (window == KITCHEN_WINDOW) {
      return KITCHEN;
    } else if (window == BUTLER_WINDOW) {
      return BUTLER_ROOM;
    } else {
      return false;
    }
  } else if (rm == KITCHEN || rm == BUTLER_ROOM) {
    return FRONT_YARD;
  } else if (rm == OFFICE_PORCH) {
    return OFFICE;
  } else if (rm == OFFICE) {
    return OFFICE_PORCH;
  } else if (rm == BACK_YARD) {
    return MONICA_ROOM;
  } else if (rm == MONICA_ROOM) {
    return BACK_YARD;
  } else if (rm == ROCK_GARDEN) {
    if (window == LINDER_WINDOW) {
      return LINDER_ROOM;
    } else if (window == BATH_WINDOW) {
      return TUB_ROOM;
    } else {
      return false;
    }
  } else if (rm == LINDER_ROOM || rm == TUB_ROOM) {
    return ROCK_GARDEN;
  } else {
    return false;
  }
}

