async function SIDE_FOOTPRINTS_F(arg = false) {
  if (arg == M_OBJDESC) {
    if (g.SIDE_FOOTPRINTS_CONFUSED) {
      if (hasFlag(SIDE_FOOTPRINTS, TOUCHBIT)) {
        tell("Fresh foot prints go here and there in the yard.\n");
        return true;
      } else {
        setFlag(SIDE_FOOTPRINTS, TOUCHBIT);
        tell("You notice fresh foot prints going here and there in the yard.\n");
        return true;
      }
    } else {
      if (hasFlag(SIDE_FOOTPRINTS, TOUCHBIT)) {
        tell("A fresh row of foot prints goes from the back yard to the driveway.\n");
        return true;
      } else {
        setFlag(SIDE_FOOTPRINTS, TOUCHBIT);
        tell("You notice a fresh row of foot prints going from the back yard to the driveway.\n");
        return true;
      }
    }
  } else if (g.SIDE_FOOTPRINTS_CONFUSED && isVerb(V.ANALYZE, V.EXAMINE)) {
    tell("There are too many foot prints here now.\n");
    return true;
  } else if (isVerb(V.EXAMINE)) {
    tell("The prints are lined up in an even row, as if made by a careful walker.\n");
    return true;
  } else if (isVerb(V.ANALYZE)) {
    if (!(eq(loc(SIDE_FOOTPRINTS_CAST), LIMBO))) {
      tell("You already did that!\n");
      return true;
    } else if (g.FINGERPRINT_OBJ || g.DUFFY_AT_CORONER) {
      await DO_FINGERPRINT();
      return true;
    } else {
      move(SIDE_FOOTPRINTS_CAST, PLAYER);
      return await ANAFOOT();
    }
  } else if (isVerb(V.FOLLOW)) {
    if (g.HERE == DRIVEWAY_ENTRANCE) {
      await GOTO(SIDE_YARD);
    } else if (g.HERE == SIDE_YARD || g.HERE == OFFICE_PATH) {
      await GOTO(DRIVEWAY_ENTRANCE);
    }
    return true;
  } else if (isVerb(V.MAKE) && (g.PRSO == BACK_FOOTPRINTS_CAST || g.PRSO == SIDE_FOOTPRINTS_CAST || g.PRSO == GENERIC_CAST)) {
    await PERFORM(V.ANALYZE, SIDE_FOOTPRINTS);
    return true;
  } else {
    return false;
  }
}

