async function RADIO_F(arg = false) {
  let pgm = 0;
  if (g.RADIO_ON && isVerb(V.LISTEN)) {
    pgm = get(g.RADIO_TABLE, 1 + div(g.PRESENT_TIME - 480, 15));
    tell("You can hardly avoid it. ");
    if (pgm == g.RADIO_ON) {
      tell("It's ");
    } else {
      tell("You spin the dial and find ");
    }
    g.RADIO_ON = pgm;
    tell(S(g.RADIO_ON), ".\n");
    return true;
  } else if (isVerb(V.LAMP_ON, V.PLAY, V.LISTEN)) {
    if (g.RADIO_ON) {
      tell("It's already on. You");
    } else {
      tell("You turn on the radio,");
    }
    g.RADIO_ON = get(g.RADIO_TABLE, 1 + div(g.PRESENT_TIME - 480, 15));
    tell(" spin the dial and find ", S(g.RADIO_ON), ".\n");
    return true;
  } else if (isVerb(V.LAMP_OFF)) {
    if (g.RADIO_ON && (loc(MONICA) == g.HERE)) {
      tell("Monica looks at you with disgust as you turn off the radio.\n");
    } else {
      tell("The radio is now off.\n");
    }
    g.RADIO_ON = false;
    return true;
  } else if (isVerb(V.TURN_UP)) {
    if (g.RADIO_ON) {
      tell("The radio is already pretty loud. Any louder would probably make the neighbors complain.\n");
      return true;
    } else {
      tell("It's not on!\n");
      return true;
    }
  } else if (isVerb(V.TURN_DOWN)) {
    if (g.RADIO_ON) {
      if ((loc(MONICA) == g.HERE) && !g.MONICA_TIED_TO) {
        tell("Monica stops you from turning down the volume. She seems strangely interested in the radio program.\n");
        return true;
      } else {
        tell("You can't.\n");
        return true;
      }
    } else {
      tell("It's not on!\n");
      return true;
    }
  } else {
    return false;
  }
}

