async function FRONT_DOOR_F() {
  let val = false;
  if (isVerb(V.KNOCK)) {
    if ((g.PRSO == FRONT_DOOR) && !g.WELCOMED && hasFlag(CORPSE, INVISIBLE)) {
      if (g.HERE == FRONT_PORCH) {
        return await WELCOME();
      } else {
        tell("You can't reach the front door.\n");
        return true;
      }
    } else if (await INHABITED$(await DOOR_ROOM(g.HERE, FRONT_DOOR))) {
      tell("A muffled voice says, \"Come in!\"\n");
      return true;
    } else {
      tell("There is no answer at the door.\n");
      return true;
    }
  } else if (isVerb(V.WALK_TO)) {
    if (g.HERE == DRIVEWAY_ENTRANCE || g.HERE == GARAGE) {
      val = true;
      await GOTO(DRIVEWAY);
    }
    if (g.HERE == DRIVEWAY || g.HERE == FRONT_YARD) {
      val = true;
      await GOTO(FRONT_PORCH);
    }
    return val;
  } else {
    return false;
  }
}

