async function COM_CHECK(per) {
  if (isVerb(V.EXAMINE)) {
    g.WINNER = PLAYER;
    await PERFORM(V.SHOW, per, g.PRSO);
    return true;
  } else if (isVerb(V.FOLLOW) && (g.PRSO == PLAYER)) {
    tell("\"I would rather not.\"\n");
    return true;
  } else if (isVerb(V.GIVE) && (g.PRSI == PLAYER)) {
    g.WINNER = PLAYER;
    await PERFORM(V.TAKE, g.PRSO, per);
    return true;
  } else if (isVerb(V.SGIVE) && (g.PRSO == PLAYER)) {
    g.WINNER = PLAYER;
    await PERFORM(V.TAKE, g.PRSI, per);
    return true;
  } else if (isVerb(V.GOODBYE) && (!g.PRSO || (g.PRSO == per))) {
    g.WINNER = PLAYER;
    await PERFORM(V.GOODBYE, g.WINNER);
    return true;
  } else if (isVerb(V.HELLO) && (!g.PRSO || (g.PRSO == per))) {
    g.WINNER = PLAYER;
    await PERFORM(V.HELLO, per);
    return true;
  } else if (isVerb(V.HELP)) {
    if ((g.PRSO == PLAYER) || !g.PRSO) {
      await PERFORM(V.GIVE, HINT, PLAYER);
      return true;
    } else if (hasFlag(g.PRSO, PERSON)) {
      tell("\"I don't need your help.\"\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.INVENTORY)) {
    tell("\"You're the detective!\"\n");
    return true;
  } else if (isVerb(V.SHOW) && (g.PRSO == PLAYER)) {
    tell("\"I'm sure you can find it, Detective.\"\n");
    return true;
  } else if (isVerb(V.TELL_ME) && (g.PRSO == PLAYER)) {
    g.WINNER = PLAYER;
    await PERFORM(V.ASK_ABOUT, per, g.PRSI);
    return true;
  } else if (isVerb(V.WAIT) || (isVerb(V.WAIT_FOR) && (g.PRSO == PLAYER))) {
    g.WINNER = PLAYER;
    await PERFORM(V.$CALL, per);
    return true;
  } else if (isVerb(V.WHAT)) {
    g.WINNER = PLAYER;
    await PERFORM(V.ASK_ABOUT, per, g.PRSO);
    return true;
  } else {
    return false;
  }
}

