async function QUEUE(rtn, tick) {
  let cint = 0;
  put(cint = await INT(rtn), C_TICK, tick);
  return cint;
}

async function INT(rtn, demon = false, e = 0, c_ = 0, int = 0) {
  e = g.C_TABLE + C_TABLELEN;
  c_ = g.C_TABLE + g.C_INTS;
  for (;;) {
    if (c_ == e) {
      g.C_INTS = g.C_INTS - C_INTLEN;
      demon && (g.C_DEMONS = g.C_DEMONS - C_INTLEN);
      int = g.C_TABLE + g.C_INTS;
      put(int, C_RTN, rtn);
      return int;
    } else if (eq(get(c_, C_RTN), rtn)) {
      return c_;
    }
    c_ = c_ + C_INTLEN;
  }
}

async function CLOCKER() {
  let c_ = 0, e = 0, tick = 0, flg = false, val = 0;
  if (g.CLOCK_WAIT) {
    g.CLOCK_WAIT = false;
    return false;
  }
  g.PRESENT_TIME = g.PRESENT_TIME + 1;
  if (g.PRESENT_TIME > 1199) {
    await TIMES_UP();
  }
  if ((g.MOVES = g.MOVES + 1) > 59) {
    g.MOVES = 0;
    if ((g.SCORE = g.SCORE + 1) > 23) {
      g.SCORE = 0;
    }
  }
  c_ = g.C_TABLE + (g.P_WON ? g.C_INTS : g.C_DEMONS);
  e = g.C_TABLE + C_TABLELEN;
  for (;;) {
    if (c_ == e) {
      return flg;
    } else if (!(get(c_, C_ENABLED$) == 0)) {
      tick = get(c_, C_TICK);
      if (tick == 0) {
      } else {
        put(c_, C_TICK, tick - 1);
        if (!(tick > 1) && (val = await apply(get(c_, C_RTN)))) {
          if (!flg || (val == M_FATAL)) {
            flg = val;
          }
        }
      }
    }
    c_ = c_ + C_INTLEN;
  }
}

async function GO() {
  restart: for (;;) {
    putb(g.P_LEXV, 0, 59);
    g.LIT = true;
    g.SCORE = 20;
    g.WINNER = PLAYER;
    g.HERE = DRIVEWAY_ENTRANCE;
    await THIS_IS_IT(FRONT_DOOR);
    await THIS_IS_S_HE(PHONG);
    g.DIFFICULTY = DIFFICULTY_MAX;
    if (!(hasFlag(g.HERE, TOUCHBIT))) {
      await QUEUE_MAIN_EVENTS();
      await START_MOVEMENT();
      await INTRO();
      await V_VERSION();
      crlf();
    }
    move(PLAYER, g.HERE);
    await V_LOOK();
    await MAIN_LOOP();
    continue restart;
  }
}

async function MAIN_LOOP() {
  let trash = 0;
  for (;;) {
    trash = await MAIN_LOOP_1();
  }
}

async function MAIN_LOOP_1() {
  let icnt = 0, ocnt = 0, num = 0, cnt = 0, obj = 0, tbl = 0, v_ = 0, ptbl = 0, obj1 = 0, tmp = 0;
  cnt = 0;
  obj = false;
  ptbl = true;
  if (!(g.QCONTEXT_ROOM == g.HERE)) {
    g.QCONTEXT = false;
  }
  if (g.P_WON = await PARSER()) {
    icnt = get(g.P_PRSI, g.P_MATCHLEN);
    num = (ocnt = get(g.P_PRSO, g.P_MATCHLEN)) == 0 ? ocnt : (ocnt > 1 ? (tbl = g.P_PRSO, icnt == 0 ? (obj = false) : (obj = get(g.P_PRSI, 1)), ocnt) : (icnt > 1 ? (ptbl = false, tbl = g.P_PRSI, obj = get(g.P_PRSO, 1), icnt) : 1));
    if (!obj && (icnt == 1)) {
      obj = get(g.P_PRSI, 1);
    }
    if (g.PRSA == V.WALK) {
      v_ = await PERFORM(g.PRSA, g.PRSO);
    } else if (num == 0) {
      if ((getb(g.P_SYNTAX, P_SBITS) & P_SONUMS) == 0) {
        v_ = await PERFORM(g.PRSA);
        g.PRSO = false;
      } else {
        tell("(There isn't anything to ");
        tmp = get(g.P_ITBL, P_VERBN);
        if (g.P_OFLAG) {
          printB(get(tmp, 0));
        } else {
          await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
        }
        tell("!)\n");
        v_ = false;
      }
    } else if (ptbl && (num > 1) && isVerb(V.ARREST, V.COMPARE)) {
      v_ = await PERFORM(g.PRSA, OBJECT_PAIR);
    } else {
      tmp = 0;
      loop1: for (;;) {
        if ((cnt = cnt + 1) > num) {
          if (tmp > 0) {
            tell("The other object");
            if (!(tmp == 1)) {
              tell("s");
            }
            tell(" that you mentioned ");
            if (!(tmp == 1)) {
              tell("are");
            } else {
              tell("is");
            }
            tell("n't here.\n");
          }
          break loop1;
        } else {
          if (ptbl) {
            obj1 = get(g.P_PRSO, cnt);
          } else {
            obj1 = get(g.P_PRSI, cnt);
          }
          if (num > 1) {
            if (obj1 == NOT_HERE_OBJECT) {
              tmp = tmp + 1;
              continue loop1;
            } else if (obj1 == PLAYER) {
              continue loop1;
            } else {
              if (obj1 == IT) {
                printD(g.P_IT_OBJECT);
              } else {
                printD(obj1);
              }
              tell(": ");
            }
          }
          v_ = await QCONTEXT_CHECK(ptbl ? obj1 : obj);
          v_ = await PERFORM(g.PRSA, ptbl ? obj1 : obj, ptbl ? obj : obj1);
          if (v_ == M_FATAL) {
            break loop1;
          }
        }
      }
    }
    if (v_ == M_FATAL) {
      g.P_CONT = false;
    }
  } else {
    g.P_CONT = false;
  }
  if (g.P_WON) {
    if (isVerb(V.TELL, V.BRIEF, V.SUPER_BRIEF, V.VERBOSE, V.TIME, V.SAVE, V.SPACE, V.UNSPACE, V.SCRIPT, V.UNSCRIPT, V.$VERIFY, V.QUIT, V.RESTART, V.$WHERE, V.DEBUG, V.$TANDY, V.VERSION)) {
      return true;
    } else {
      return v_ = await CLOCKER();
    }
  } else {
    return false;
  }
}

async function QCONTEXT_CHECK(prso) {
  let other = 0, who = false, n_ = 0;
  if (isVerb(V.HELP, V.WHAT) || (isVerb(V.SHOW, V.TELL_ME) && (prso == PLAYER))) {
    other = first(g.HERE);
    loop1: for (;;) {
      if (!other) {
        break loop1;
      } else if (hasFlag(other, PERSON)) {
        n_ = 1 + n_;
        who = other;
      }
      other = next(other);
    }
    if ((1 == n_) && !g.QCONTEXT) {
      await SAID_TO(who);
    }
    if (g.QCONTEXT && (loc(g.QCONTEXT) == g.HERE) && (g.QCONTEXT_ROOM == g.HERE) && (g.WINNER == PLAYER)) {
      g.WINNER = g.QCONTEXT;
      tell("(said to ", D(g.QCONTEXT), ")\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function SAID_TO(who) {
  g.WINNER = who;
  g.QCONTEXT = who;
  return g.QCONTEXT_ROOM = g.HERE;
}

async function FAKE_ORPHAN() {
  let tmp = 0;
  await ORPHAN(g.P_SYNTAX, false);
  tell("(Be specific: what object do you want to ");
  tmp = get(g.P_OTBL, P_VERBN);
  if (tmp == 0) {
    tell("tell");
  } else if (getb(g.P_VTBL, 2) == 0) {
    printB(get(tmp, 0));
  } else {
    await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
    putb(g.P_VTBL, 2, 0);
  }
  g.P_OFLAG = true;
  g.P_WON = false;
  tell("?)\n");
  return true;
}

async function PERFORM(a_, o = false, i = false) {
  let v_ = 0, oa = 0, oo = 0, oi = 0;
  if (g.DEBUG) {
    tell("[Perform: ");
    tell(N(a_));
    if (o && !(a_ == V.WALK)) {
      tell("/", D(o));
    }
    if (i) {
      tell("/", D(i));
    }
    tell("]\n");
  }
  oa = g.PRSA;
  oo = g.PRSO;
  oi = g.PRSI;
  g.PRSA = a_;
  if (!(a_ == V.WALK)) {
    if ((IT == i || IT == o) && !(g.P_IT_LOC == g.HERE)) {
      if (!i) {
        await FAKE_ORPHAN();
      } else {
        tell("(The ", D(g.P_IT_OBJECT), " isn't here!)\n");
      }
      return M_FATAL;
    } else if ((HIM_HER == i || HIM_HER == o) && !(eq(await META_LOC(g.P_HIM_HER), g.HERE))) {
      g.P_HIM_HER = get(g.GLOBAL_CHARACTER_TABLE, getProp(g.P_HIM_HER, P.CHARACTER));
    }
  }
  if (o == IT) {
    o = g.P_IT_OBJECT;
  } else if (o == HIM_HER) {
    o = g.P_HIM_HER;
  }
  if (i == IT) {
    i = g.P_IT_OBJECT;
  } else if (i == HIM_HER) {
    i = g.P_HIM_HER;
  }
  g.PRSO = o;
  if (g.PRSO && !(isVerb(V.WALK))) {
    if (hasFlag(g.PRSO, PERSON)) {
      g.P_HIM_HER = g.PRSO;
      g.P_HIM_HER_LOC = g.HERE;
    } else {
      g.P_IT_OBJECT = g.PRSO;
      g.P_IT_LOC = g.HERE;
    }
  }
  g.PRSI = i;
  if (((NOT_HERE_OBJECT == g.PRSO || NOT_HERE_OBJECT == g.PRSI) && (v_ = (await D_APPLY("Not Here", NOT_HERE_OBJECT_F.id))))) {
  } else if ((o = g.PRSO) && (i = g.PRSI) && (await NULL_F())) {
    tell("[in case last clause changed PRSx]");
  } else if ((v_ = (await DD_APPLY("Actor", g.WINNER, getProp(g.WINNER, P.ACTION))))) {
  } else if ((v_ = (await D_APPLY("Room (M-BEG)", getProp(loc(g.WINNER), P.ACTION), M_BEG)))) {
  } else if ((v_ = (await D_APPLY("Preaction", get(g.PREACTIONS, a_))))) {
  } else if ((i && (g.NOW_PRSI = true) && (v_ = (await D_APPLY("PRSI", getProp(i, P.ACTION)))))) {
  } else if ((!(g.NOW_PRSI = false) && o && !(a_ == V.WALK) && loc(o) && getProp(loc(o), P.CONTFCN) && (v_ = (await DD_APPLY("Container", loc(o), getProp(loc(o), P.CONTFCN)))))) {
  } else if ((o && !(a_ == V.WALK) && (v_ = (await D_APPLY("PRSO", getProp(o, P.ACTION)))))) {
  } else if (v_ = await D_APPLY(false, get(g.ACTIONS, a_))) {
  }
  if (!(v_ == M_FATAL)) {
    if (eq(loc(g.WINNER), g.PRSO)) {
      g.PRSO = false;
    }
    (v_ = (await D_APPLY("Room (M-END)", getProp(loc(g.WINNER), P.ACTION), M_END)));
  }
  g.PRSA = oa;
  g.PRSO = oo;
  g.PRSI = oi;
  return v_;
}

async function DD_APPLY(str, obj, fcn, foo = false) {
  if (g.DEBUG) {
    tell("[", D(obj), "=]");
  }
  return await D_APPLY(str, fcn, foo);
}

async function D_APPLY(str, fcn, foo = false) {
  let res = 0;
  if (!fcn) {
    return false;
  } else {
    if (g.DEBUG) {
      if (!str) {
        tell("[Action:]\n");
      } else {
        tell("[", S(str), ": ");
      }
    }
    res = foo ? (await apply(fcn, foo)) : (await apply(fcn));
    if (g.DEBUG && str) {
      if (res == M_FATAL) {
        tell("Fatal]\n");
      } else if (!res) {
        tell("Not handled]\n");
      } else {
        tell("Handled]\n");
      }
    }
    return res;
  }
}

