async function DO_FINGERPRINT(an = false) {
  if (g.DUFFY_AT_CORONER) {
    tell("Don't you remember? Duffy went in the ambulance to the Coroner's office. You'll have to wait for him to return.\n");
    return true;
  } else if (g.FINGERPRINT_OBJ) {
    tell("Sergeant Duffy ran off to the lab on an errand for you. You'll have to wait for him to return.\n");
    return true;
  }
  if (!g.MET_DUFFY$) {
    tell("You haven't met Sergeant Duffy yet tonight. You'll need his help to do that.\n");
    return true;
  }
  if (!an) {
    tell("You look at the ", D(g.PRSO), " closely. It appears to have good fingerprints on it, so you call for Sergeant Duffy.\n");
  }
  if (an && g.PRSI) {
    g.ANALYSIS_GOAL = g.PRSI;
  } else {
    g.ANALYSIS_GOAL = false;
  }
  g.FINGERPRINT_OBJ = g.PRSO;
  g.ANALYSIS_OBJ = an;
  enable(await QUEUE(I_FINGERPRINT.id, 15 + random(15)));
  setFlag(g.PRSO, TOUCHBIT);
  remove(g.PRSO);
  tell("Sergeant Duffy, quiet as a mouse, walks up and takes the ", D(g.PRSO), " from you. \"I'll return soon with the results,\" he says, and leaves as silently as he came.\n");
  return true;
}

