async function I_FINGERPRINT() {
  tell("Suddenly, Sergeant Duffy ");
  if (30 > random(100)) {
    tell("appears, holding the ", D(g.FINGERPRINT_OBJ), " carefully in his hands. His quiet efficiency is impressive. ");
  } else if (50 > random(100)) {
    tell("seems to arrive from nowhere, holding the ", D(g.FINGERPRINT_OBJ), " in his hands. ");
  } else {
    tell("returns with the ", D(g.FINGERPRINT_OBJ), ". For a moment you muse on his almost magical appearances. ");
  }
  if (g.ANALYSIS_GOAL) {
    if ((g.FINGERPRINT_OBJ == INSIDE_GUN || g.FINGERPRINT_OBJ == OUTSIDE_GUN) && (g.ANALYSIS_GOAL == POWDER || g.ANALYSIS_GOAL == CLOCK_POWDER)) {
      tell("\"The gun has recently been fired, and it contains traces of cheap gun powder");
      if (g.POWDER_ANALYZED) {
        tell(", the same kind of powder that you found on the clock");
      }
      tell(".");
    } else if ((g.FINGERPRINT_OBJ == MATCHBOOK || g.FINGERPRINT_OBJ == THREAT_NOTE) && (g.ANALYSIS_GOAL == HANDWRITING)) {
      tell("\"The ink is ordinary Waterman blue-black. The lab can't tell much else without a certified handwriting sample on file.");
    } else if (!(g.FINGERPRINT_OBJ == g.ANALYSIS_GOAL)) {
      tell("\"The ", D(g.FINGERPRINT_OBJ), " doesn't contain any ");
      await ANALYSIS_PRINT(g.ANALYSIS_GOAL);
    }
  } else if ((g.FINGERPRINT_OBJ == PIECE_OF_WIRE || g.FINGERPRINT_OBJ == SPOOL_OF_WIRE) || (g.FINGERPRINT_OBJ == WHITE_WIRE || g.FINGERPRINT_OBJ == BLACK_WIRE)) {
    tell("\"The wire is ordinary 16-gauge bell wire.");
  } else if (g.FINGERPRINT_OBJ == PIECE_OF_PUTTY) {
    tell("\"The putty contained traces of the explosive cordite.");
  } else if (g.FINGERPRINT_OBJ == INSIDE_GUN || g.FINGERPRINT_OBJ == OUTSIDE_GUN) {
    tell("\"The gun has recently been fired, and it contains traces of cheap gun powder");
    tell(".");
    if (g.FINGERPRINT_OBJ == INSIDE_GUN) {
      tell(" And the barrel has indeed been sawed off.");
    }
  } else if (g.FINGERPRINT_OBJ == CLOCK_POWDER) {
    g.POWDER_ANALYZED = true;
    tell("\"The powder is gun powder, as I suspected. I put it in a cellophane envelope for you.");
  } else if (g.FINGERPRINT_OBJ == MATCHBOOK || g.FINGERPRINT_OBJ == THREAT_NOTE) {
    tell("\"The ink is ordinary Waterman blue-black. The lab can't tell much else without a certified handwriting sample on file.");
  } else if (g.FINGERPRINT_OBJ == STUB) {
    tell("\"I took the ticket stub to the movie theater, where they told me that it looked authentic to them, and the serial number proves that it was bought tonight.");
  } else if (g.FINGERPRINT_OBJ == MEDICAL_REPORT) {
    g.DUFFY_SAW_MEDICAL_REPORT = true;
    tell("\"I tried to call the doctor, but there's no listing in the phone book. The lab people couldn't see anything unusual about the report.");
  } else {
    tell("\"I'm sorry,\" he begins, \"but the lab found nothing interesting.");
  }
  tell("\" With that, he leaves, handing you the ", D(g.FINGERPRINT_OBJ), " as he whisks away.\n");
  move(g.FINGERPRINT_OBJ, PLAYER);
  g.FINGERPRINT_OBJ = false;
  return true;
}

