async function FIX_PHONG_MOVEMENT() {
  let mg = 0, elapsed = 0, ot = 0;
  mg = get(g.MOVEMENT_GOALS, PHONG_C);
  elapsed = g.PRESENT_TIME - 480;
  for (;;) {
    if ((ot = get(mg, MG_TIME)) == 0) {
      return true;
    }
    if (1 > (ot = ot - elapsed)) {
      g.TOO_LATE = true;
      return false;
    }
    put(mg, MG_TIME, ot);
    mg = mg + MG_LENGTH;
  }
}

