async function ROB(what, thief, prob_ = false) {
  let n_ = 0, x = 0, robbed$ = false;
  x = first(what);
  for (;;) {
    if (!x) {
      return robbed$;
    }
    n_ = next(x);
    if (!(hasFlag(x, INVISIBLE)) && (!prob_ || (prob_ > random(100)))) {
      move(x, thief);
      robbed$ = true;
    }
    x = n_;
  }
}

